import re, subprocess, sys
r = subprocess.run([sys.executable, "_tools/benchmarks.py", "multi", "run", "coord", "--replay", "--plant", "land-stop", "--dry-run"], capture_output=True, text=True)
o = r.stdout + r.stderr
if r.returncode != 0: print("repro: the dry run failed", r.returncode); sys.exit(1)
blocks = re.split(r"^(?=agent )", o, flags=re.M)
ag = [(m.group(1), m.group(2), "plant: land-stop" in b) for b in blocks for m in [re.match(r"agent (code-\d+): .*?item (\S+)", b)] if m]
if not any(a == "code-1" for a, i, p in ag): print("repro: the dry run names no code agent"); sys.exit(1)
items = {i for a, i, p in ag if p}
peers = [a for a, i, p in ag if i in items and not p]
if peers and "started at once" in o:
    print("repro: the planted code agent shares its item with", peers, "started at once: whichever claims first does the work, so the plant may never land"); sys.exit(1)
print("ok", ag)

